data.minimal_example:
TimesSlotGridViewFromInterval(
  locale: "en",
  initTime: selectTime,
  crossAxisCount: 4,
  timeSlotInterval: const TimeSlotInterval(
    start: TimeOfDay(hour: 10, minute: 00),
    end: TimeOfDay(hour: 22, minute: 0),
    interval: Duration(hours: 1, minutes: 0),
  ),
  onChange: (value) {
    setState(() {
      selectTime = value;
    });
  },
)
